(function(){
  'use strict';
  const C=window.KOMPAS_CATALOG, E=window.KOMPAS_ENGINE, S=window.KOMPAS_STORE, A=window.KOMPAS_ASSISTANT;
  const W=window.KOMPAS_WORKFLOW, SS=window.KOMPAS_SESSION, F=window.KOMPAS_FIRST_RULES, D=window.KOMPAS_DEMO;
  const steps=()=>W.getSteps(state.case.track);
  let state=S.load();
  let onlineConsent=false; // transient, never auto-enabled on reload
  let demoMenuOpen=false;
  let assistantOpen=false; // UI-only: initially closed on every page load
  let assistantDraft=""; // preserve unfinished question when rerendering
  let prototypeDetailsOpen=false;
  let browserAiLoading=false;
  let browserAiProgress='';
  const browserAi=window.KOMPAS_BROWSER_LLM;
  const root=document.getElementById('app');
  const q=sel=>document.querySelector(sel);
  const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmtDate=s=>{if(!s)return '—';const p=s.split('-');return p.length===3?`${p[2]}.${p[1]}.${p[0]}`:s;};
  const initials=s=>(s||'?').trim().split(/\s+/).map(t=>t.charAt(0)).slice(0,2).join('').toUpperCase();
  const levelLabel=n=>E.levelName(n);
  const smallStamp=(text,type='neutral')=>`<span class="stamp stamp-${type}">${text}</span>`;
  const button=(label,action,extra='',type='secondary')=>`<button type="button" class="btn btn-${type}" data-action="${action}" ${extra}>${label}</button>`;
  const textarea=(name,label,value,placeholder,rows=3)=>`<label class="field-label" for="f-${name}">${label}</label><textarea id="f-${name}" class="field-control" rows="${rows}" name="${name}" placeholder="${escapeHtml(placeholder||'')}" data-field="1">${escapeHtml(value||'')}</textarea>`;
  function save(){S.save(state);}
  function notify(text){state.notice=text;save();render();}
  function invalidate(){SS.invalidate(state);}
  function currentStatus(){if(state.finalized)return ['Zakończona','success']; if(state.step>=3)return ['W trakcie oceny','warning'];return ['W przygotowaniu','neutral'];}
  function renderHeader(){
    const status=currentStatus();
    return `<header class="app-header"><div class="header-left"><div class="brand-symbol" aria-hidden="true"><span class="brand-needle">✦</span></div><div class="brand-text"><strong>kompas<span>kompetencji</span></strong><small>HACKNATION 2026 · PROTOTYP</small></div><div class="header-divider"></div><div class="header-context">Środowisko demonstracyjne <span class="header-dot"></span> <b>Offline ready</b></div></div><div class="header-actions"><button type="button" class="header-assistant-toggle" data-action="toggle-assistant" aria-expanded="${assistantOpen}" aria-controls="knowledge-assistant" aria-label="${assistantOpen?'Zamknij asystenta wiedzy':'Otwórz asystenta wiedzy'}"><span aria-hidden="true">✳</span> Asystent</button>${smallStamp(status[0],status[1])}<div class="avatar" title="Rola demonstracyjna: Przełożony">MZ</div></div></header>`;
  }
  function stepAllowed(n){return E.nextGuard(state,n).ok;}
  function renderSidebar(){
    const t=E.totals(state);
    const percent=Math.round((t.answered/Math.max(1,t.total))*100);
    return `<aside class="sidebar"><div class="side-nav-title">PRZESTRZEŃ ROBOCZA</div><div class="nav-group">
      <button class="nav-primary ${state.view==='workflow'?'active':''}" data-action="switch-view" data-view="workflow"><span class="nav-ico">◈</span><span>Proces oceny</span><span class="nav-bullet"></span></button>
      <button class="nav-primary ${state.view==='hr'?'active':''}" data-action="switch-view" data-view="hr"><span class="nav-ico">▦</span><span>Panel HR</span><span class="nav-bullet"></span></button>
    </div><div class="side-nav-title section-label">ETAPY OCENY</div><div class="steps" aria-label="Etapy oceny">${steps().map((x,i)=>`<button class="step-link ${state.view==='workflow'&&state.step===i?'active':''} ${i<state.step?'completed':''}" data-action="go-step" data-step="${i}" aria-current="${state.view==='workflow'&&state.step===i?'step':'false'}"><span class="step-number">${i<state.step?'✓':i+1}</span><span class="step-label"><strong>${x.title}</strong><small>${x.subtitle}</small></span></button>`).join('')}</div>
    <div class="sidebar-bottom"><div class="side-progress-heading"><span>Wskaźniki ocenione</span><b>${percent}%</b></div><div class="progress-track"><div style="width:${percent}%" class="progress-fill"></div></div><p>${t.answered} z ${t.total} wskazań</p><div class="sidebar-separator"></div><p class="privacy-line"><span>⌁</span> Dane zapisane tylko w tej karcie przeglądarki</p></div></aside>`;
  }
  function renderNotice(){return state.notice?`<div class="notice" role="status"><span class="notice-icon">i</span><span>${escapeHtml(state.notice)}</span><button class="notice-close" data-action="clear-notice" aria-label="Zamknij komunikat">×</button></div>`:'';}
  function renderDemoBanner(){
    const item=D.current(state);if(!item)return '';
    const questions=item.questions?.length?`<p class="demo-questions"><strong>Pytania do sprawdzenia:</strong> ${item.questions.map(escapeHtml).join(' · ')}</p>`:'';
    return `<section class="demo-active-banner" role="status"><span aria-hidden="true">◈</span><div><strong>Scenariusz testowy: ${escapeHtml(item.label)}</strong><p>Oczekiwane zachowanie: ${escapeHtml(item.expected)}</p>${questions}</div><button class="btn btn-subtle" data-action="end-demo" type="button">Przywróć sesję</button></section>`;
  }
  function renderDemoPicker(){
    const items=D.scenarios.map(item=>`<button type="button" class="demo-menu-item" data-action="start-demo" data-id="${item.id}"><strong>${escapeHtml(item.label)}</strong><small>${escapeHtml(item.description)}</small></button>`).join('');
    return `<div class="demo-picker"><button type="button" class="btn btn-subtle demo-picker-trigger" data-action="toggle-demo-menu" aria-expanded="${demoMenuOpen}" aria-controls="demo-scenario-menu">Scenariusze testowe <span aria-hidden="true">⌄</span></button>${demoMenuOpen?`<div class="demo-menu" id="demo-scenario-menu" role="group" aria-label="Wybierz scenariusz testowy"><div class="demo-menu-caption">Dane fikcyjne · ocena wykonywana przez silnik</div>${items}</div>`:''}</div>`;
  }
  function renderMain(){return `<main class="main-area" id="main-content" tabindex="-1">${renderNotice()}${renderDemoBanner()}${state.view==='workflow'?renderWizard():renderHR()}</main>`;}
  function pageHeading(kicker,title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="lead">${subtitle}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;}
  function renderPrototypeNotice(){
    const isFirst=state.case.track==='first';
    const heading=isFirst?'Prototyp demonstracyjny · dane fikcyjne · raport nieurzędowy':'Ocena okresowa — wersja demonstracyjna, nieurzędowa';
    const explanation=isFirst
      ? 'Ścieżka pierwszej oceny zawiera elementy i skalę z rozporządzenia Dz.U. 2015 poz. 1144. Opisy zachowań, ich skala pomocnicza oraz wydruk nie zastępują modelu ani formularza urzędowego.'
      : 'Ścieżka oceny okresowej jest demonstracyjna: wykorzystuje przykładowe kompetencje i skalę zachowań, nie pełną metodę ani urzędowy formularz z rozporządzenia Dz.U. 2016 poz. 470. Nie należy używać jej do rzeczywistej oceny pracowniczej.';
    return `<div class="prototype-note" role="note"><span class="prototype-note-icon" aria-hidden="true">ⓘ</span><div class="prototype-note-copy"><strong>${heading}</strong><p class="prototype-extra" id="prototype-more" ${prototypeDetailsOpen?'':'hidden'}>${explanation}</p></div><button type="button" class="prototype-more-button" data-action="toggle-prototype-details" aria-expanded="${prototypeDetailsOpen}" aria-controls="prototype-more">${prototypeDetailsOpen?'Mniej':'Szczegóły'} <span aria-hidden="true">${prototypeDetailsOpen?'⌃':'⌄'}</span></button></div>`;
  }
  function renderWizard(){
    let content;
    switch(W.current(state)?.id){case 'start':content=renderStart();break;case 'criteria':content=renderCriteria();break;case 'observations':content=renderObservations();break;case 'decisions':content=renderDecisions();break;case 'meeting':case 'development':content=renderMeeting();break;default:content=renderDocument();}
    return `${content}${renderFooter()}`;
  }
  function inputField(name,label,value,type='text',hint=''){
    return `<div class="field"><label class="field-label" for="f-${name}">${label}</label><input id="f-${name}" class="field-control" type="${type}" name="${name}" data-field="1" value="${escapeHtml(value)}">${hint?`<p class="field-hint">${hint}</p>`:''}</div>`;
  }
  function selectField(name,label,value,options,help=''){
    return `<div class="field"><label class="field-label" for="f-${name}">${label}</label><select class="field-control" id="f-${name}" name="${name}" data-field="1">${options.map(([v,t])=>`<option value="${escapeHtml(v)}" ${value===v?'selected':''}>${escapeHtml(t)}</option>`).join('')}</select>${help?`<p class="field-hint">${help}</p>`:''}</div>`;
  }
  function renderStart(){
    const c=state.case,f=state.firstFormal;
    return `${pageHeading('ETAP 01 / 06','Rozpocznij ocenę','Wybierz ścieżkę i przygotuj podstawowe informacje o procesie.',renderDemoPicker())}
    ${renderPrototypeNotice()}
    <section class="section-block"><div class="section-title"><h2>Rodzaj oceny</h2><p>Wybierz właściwą procedurę</p></div><div class="track-grid">${Object.values(C.tracks).map(t=>`<button class="track-card ${c.track===t.id?'selected':''}" data-action="choose-track" data-id="${t.id}" aria-pressed="${c.track===t.id}"><span class="track-top"><span class="track-ico">${t.id==='periodic'?'↻':'✳'}</span><span class="round-radio">${c.track===t.id?'●':'○'}</span></span><strong>${t.name}</strong><span>${t.description}</span></button>`).join('')}</div></section>
    <section class="panel"><div class="section-title"><h2>Dane procesu</h2><p>Wykorzystywane w raporcie roboczym</p></div><div class="form-grid">${inputField('case.employee','Imię i nazwisko pracownika',c.employee)}${inputField('case.position','Stanowisko',c.position)}${inputField('case.manager','Osoba oceniająca',c.manager)}${inputField('case.department','Komórka organizacyjna',c.department)}${inputField('case.periodStart','Początek okresu',c.periodStart,'date')}${inputField('case.periodEnd','Koniec okresu',c.periodEnd,'date')}${inputField('case.due','Planowany termin zakończenia',c.due,'date')}</div></section>
    ${c.track==='first'?`<section class="panel"><div class="section-title"><h2>Terminy pierwszej oceny</h2><p>§ 3–4 rozporządzenia z 23 lipca 2015 r. oraz art. 38 ustawy o służbie cywilnej</p></div><div class="form-grid">${inputField('firstFormal.employmentDate','Data nawiązania stosunku pracy',f.employmentDate,'date')}${inputField('firstFormal.contractEnd','Koniec umowy terminowej',f.contractEnd,'date')}${inputField('firstFormal.introMeetingDate','Rozmowa wstępna (data)',f.introMeetingDate,'date')}${inputField('firstFormal.reportDue','Wyznaczony termin sprawozdania',f.reportDue,'date')}</div><p class="field-hint">Rozmowa wstępna: co do zasady w ciągu 21 dni; termin sprawozdania należy ustalić z uwzględnieniem okresu co najmniej 8 miesięcy. Zmiany terminów i szczególne przypadki wymagają indywidualnej weryfikacji.</p><a href="https://eli.gov.pl/api/acts/DU/2015/1144/text.html" target="_blank" rel="noopener noreferrer">Źródło: rozporządzenie Dz.U. 2015 poz. 1144</a></section>`:''}`;
  }
  function renderCriteria(){
    const first=state.case.track==='first';
    const collection=first?F.IDS.map(id=>E.getCompetency(id)):C.competencies;
    return `${pageHeading('ETAP 02 / 06',first?'Pięć elementów pierwszej oceny':'Wybierz kompetencje',first?'Elementy są obowiązkowe i wynikają z § 2 ust. 1 pkt 1 rozporządzenia Dz.U. 2015 poz. 1144.':'Zaznacz obszary oceniane na podstawie zaobserwowanych zachowań.',smallStamp(state.selected.length+' wybrano','info'))}
      <div class="info-banner"><span class="info-icon">ⓘ</span><div><strong>${first?'Nazwy elementów: akt prawny; wskaźniki: pomocnicze':'Model demonstracyjny'}</strong><p>${first?'Pięć elementów pierwszej oceny wynika z § 2 rozporządzenia. Pytania behawioralne w kolejnych krokach służą zebraniu obserwacji i nie są wiernym odwzorowaniem załącznika nr 1.':'Poniższe czterostopniowe wskaźniki pozostają przykładowe i nie zastępują oficjalnych kryteriów okresowej oceny.'}</p></div></div>
      <section class="criterion-list">${collection.filter(Boolean).map(x=>{const chosen=state.selected.includes(x.id);return `<button ${first?'disabled aria-disabled="true"':''} data-action="toggle-criterion" data-id="${x.id}" class="criterion-card ${chosen?'chosen':''}" aria-pressed="${chosen}"><div class="criterion-glyph">▣</div><div class="criterion-copy"><div class="criterion-title"><strong>${escapeHtml(x.name)}</strong><span>${first?'Kryterium obowiązkowe':escapeHtml(x.category)}</span></div><p>${escapeHtml(x.description)}</p><small>${x.indicators.length} przykładowe obserwacje</small></div><div class="square-check">${chosen?'✓':''}</div></button>`;}).join('')}</section>`;
  }
  function renderObservations(){
    const t=E.totals(state);
    return `${pageHeading('ETAP 03 / 06','Oceń zachowania','Dla każdego wskaźnika wybierz opis najbliższy zaobserwowanej częstotliwości i samodzielności.',smallStamp(t.answered+'/'+t.total+' wskaźników','info'))}<div class="scale-card"><strong>Skala demonstracyjna</strong><div class="scale-line">${C.levels.map(l=>`<span><b>${l.value}</b> ${l.short}</span>`).join('')}</div></div>
      ${state.selected.map((id,j)=>{const co=E.getCompetency(id);if(!co)return '';const total=co.indicators.filter((_,i)=>state.observations[E.key(id,i)]?.level).length;return `<section class="observation-group"><div class="obs-group-head"><div class="obs-num">${String(j+1).padStart(2,'0')}</div><div><h2>${co.name}</h2><p>${co.description}</p></div>${smallStamp(total+'/'+co.indicators.length, total===co.indicators.length?'success':'neutral')}</div>${co.indicators.map((label,i)=>{const k=E.key(id,i);const item=state.observations[k]||{};return `<div class="indicator"><div class="indicator-title"><span class="indicator-index">${j+1}.${i+1}</span><strong>${label}</strong></div><div class="rating-row" role="group" aria-label="Ocena wskaźnika ${j+1}.${i+1}">${C.levels.map(l=>`<button class="rating ${item.level===l.value?'is-selected':''}" data-action="rate" data-id="${id}" data-index="${i}" data-level="${l.value}" aria-pressed="${item.level===l.value}" title="${escapeHtml(l.description)}"><b>${l.value}</b><span>${l.short}</span></button>`).join('')}</div><div class="observation-note"><label for="note-${id}-${i}">Przykład / dowód (opcjonalnie, zalecane)</label><textarea id="note-${id}-${i}" class="note-input" name="observations.${k}.note" data-field="1" rows="2" placeholder="Np. konkretna sytuacja, rezultat, data...">${escapeHtml(item.note||'')}</textarea></div></div>`;}).join('')}</section>`;}).join('')}`;
  }
  function renderPeriodicDecisions(){const t=E.totals(state);return `${pageHeading('ETAP 04 / 06','Rekomendacja i decyzja','Sprawdź wynik obliczeń. System doradza, ale końcową ocenę ustala wyłącznie przełożony.',smallStamp(t.decisions+'/'+t.criteria+' zatwierdzono','info'))}
    <div class="info-banner"><span class="info-icon">∑</span><div><strong>Jawna reguła MVP</strong><p>Równe wagi wszystkich wskaźników. Sugestia = zaokrąglona średnia ocen 1–4. To algorytm demonstracyjny, a nie oficjalna metoda oceniania.</p></div></div>
    ${t.summaries.map((s,i)=>{if(!s.completed)return '';const chosen=s.final||0;return `<section class="decision-card"><div class="decision-head"><div class="decision-index">${String(i+1).padStart(2,'0')}</div><div><h2>${s.competency.name}</h2><p>${s.competency.description}</p></div></div><div class="decision-metrics"><div><span>Średnia obserwacji</span><b>${s.average.toFixed(2).replace('.',',')} <small>/ 4,00</small></b></div><div><span>Sugestia systemu</span><b>${s.suggestion} · ${levelLabel(s.suggestion)}</b></div></div><div class="decision-select-title">Ostateczna ocena przełożonego <span>— wybierz poziom</span></div><div class="decision-options">${C.levels.map(l=>`<button class="decision-option ${chosen===l.value?'selected':''}" data-action="decide" data-id="${s.competency.id}" data-level="${l.value}" aria-pressed="${chosen===l.value}"><b>${l.value}</b><span>${l.name}</span>${l.value===s.suggestion?'<small>● sugestia</small>':''}</button>`).join('')}</div>${s.overruled?`<div class="override-reason">${textarea('decisions.'+s.competency.id+'.reason','Uzasadnienie odstąpienia od sugestii *',state.decisions[s.competency.id]?.reason,'Wskaż konkretne obserwacje przemawiające za zmianą.',2)}${!s.validDecision?'<p class="validation-warning">Wymagane minimum 8 znaków.</p>':''}</div>`:''}${s.validDecision?'<div class="decision-confirm">✓ Ocena potwierdzona przez przełożonego</div>':'<div class="decision-pending">Wybierz ostateczną ocenę, aby kontynuować.</div>'}</section>`;}).join('')}`;}
  function renderFirstDecisions(){
    const f=state.firstFormal, result=F.evaluate(f),t=E.totals(state);
    return `${pageHeading('ETAP 04 / 06','Oceny cząstkowe i wynik pierwszej oceny','Przełożony wybiera ocenę 3, 5 lub 7 dla każdego z pięciu obowiązkowych elementów (§ 9).',smallStamp(result.values.filter(F.validGrade).length+'/5 ocen','info'))}
      <div class="info-banner"><span class="info-icon">ⓘ</span><div><strong>Skala z § 9 ust. 1 rozporządzenia</strong><p>3 pkt – poniżej oczekiwań; 5 pkt – na poziomie oczekiwań; 7 pkt – powyżej oczekiwań. Dane behawioralne 1–4 z poprzedniego etapu są jedynie materiałem pomocniczym — nie są automatycznie przenoszone na formalną ocenę.</p></div></div>
      ${F.IDS.map((id,i)=>{const co=E.getCompetency(id),sum=E.summaryFor(state,id),selected=f.grades?.[id];return `<section class="decision-card"><div class="decision-head"><div class="decision-index">${String(i+1).padStart(2,'0')}</div><div><h2>${escapeHtml(co.name)}</h2><p>Pomocnicze obserwacje: ${sum?.values.join(' / ')||'brak'} (skala 1–4). Przed wyborem weź pod uwagę opis elementu oceny z załącznika nr 1.</p></div></div><div class="decision-select-title">Ocena cząstkowa ustalona przez przełożonego</div><div class="decision-options">${F.LEVELS.map(l=>`<button class="decision-option ${selected===l.value?'selected':''}" data-action="grade-first" data-id="${id}" data-level="${l.value}" aria-pressed="${selected===l.value}"><b>${l.value}</b><span>${l.name}</span></button>`).join('')}</div></section>`}).join('')}
      <section class="panel"><div class="section-title"><h2>Warunki pierwszej oceny (§ 10)</h2><p>System oblicza ocenę łączną na podstawie ocen cząstkowych i sprawdza warunki wyniku pozytywnego.</p></div><div class="form-grid">${selectField('firstFormal.examStatus','Egzamin ze służby przygotowawczej',f.examStatus,[['unknown','Nie ustalono'],['passed','Zaliczony'],['failed','Niezaliczony'],['exempt','Nie dotyczy (§ 10 ust. 3)']])}${f.examStatus==='exempt'?selectField('firstFormal.exemptionKind','Podstawa wyłączenia obowiązku egzaminu',f.exemptionKind,[['','Wybierz podstawę'],['ksap','Absolwent KSAP (bez wniosku o mianowanie)'],['replacement','Zatrudnienie w celu zastępstwa'],['senior','Zatrudnienie na wyższym stanowisku']]):''}${selectField('firstFormal.reportOnTime','Sprawozdanie złożone w terminie',f.reportOnTime,[['unknown','Nie ustalono'],['yes','Tak'],['no','Nie']])}${inputField('firstFormal.assessmentMeetingDate','Rozmowa oceniająca (data)',f.assessmentMeetingDate,'date')}</div>
      <div class="tip-card"><strong>Wynik według wybranych danych</strong><p>Ocena łączna (średnia pięciu ocen): <b>${result.average===null?'Brak kompletu ocen':result.average.toFixed(2).replace('.',',')+' pkt'}</b>. Ocen cząstkowych po 3 pkt: <b>${result.lowCount}</b>.</p><p><b>${result.result?('Ocena '+result.result):'Wynik nieustalony – uzupełnij wszystkie pola'}</b></p>${result.negativeReasons.length?`<ul>${result.negativeReasons.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`:''}</div>
      ${result.result==='negatywna'?textarea('firstFormal.negativeReason','Uzasadnienie oceny negatywnej – wymagane (§ 10 ust. 4)',f.negativeReason,'Wprowadź konkretne, rzeczowe uzasadnienie.',3):''}
      <p class="field-hint">Źródło: <a href="https://eli.gov.pl/api/acts/DU/2015/1144/text.html" target="_blank" rel="noopener noreferrer">Dz.U. 2015 poz. 1144, § 7, 9–10</a>. Ostateczne oceny cząstkowe ustala człowiek. Zastosowanie w realnych aktach osobowych wymaga weryfikacji i właściwego urzędowego formularza.</p></section>`;
  }
  function renderDecisions(){return state.case.track==='first'?renderFirstDecisions():renderPeriodicDecisions();}
  function renderMeeting(){const m=state.meeting,first=state.case.track==='first';return `${pageHeading('ETAP 05 / 06',first?'Rozmowa i plan rozwoju':'Przygotuj rozmowę',first?'Omów ocenę po złożeniu sprawozdania lub po upływie terminu. Wnioski rozwojowe są fakultatywne (§ 7 i § 10).':'Uporządkuj argumenty i ustalenia, zanim spotkasz się z pracownikiem.',button('Zaproponuj pytania','suggest-questions','','subtle'))}
    <div class="panel"><div class="section-title"><h2>Plan rozmowy oceniającej</h2><p>Asystent może pomóc sformułować pytania, ale nie zastępuje rozmowy ani decyzji przełożonego.</p></div><div class="meeting-fields"><div>${textarea('meeting.strengths','Mocne strony i osiągnięcia',m.strengths,'Konkrety: co się udało i jakie były efekty?')}</div><div>${textarea('meeting.areas','Obszary do rozwoju',m.areas,'Zaobserwowane zachowania i oczekiwana zmiana')}</div><div>${textarea('meeting.questions','Pytania do pracownika',m.questions,'Jak oceniasz ten okres? Co pomogłoby w rozwoju?')}</div><div>${textarea('meeting.actions','Ustalenia i kolejne działania',m.actions,'Działania, odpowiedzialności, termin kolejnego przeglądu')}</div></div></div><div class="tip-card"><strong>Proponowana struktura spotkania</strong><ol><li>Przywołaj cel rozmowy i oceniany okres.</li><li>Omów zachowania, przykłady i skutki.</li><li>Zapytaj o perspektywę pracownika.</li><li>Ustal konkretne działania rozwojowe.</li></ol></div>`;}
  function renderPeriodicDocument(){const t=E.totals(state);return `${pageHeading('ETAP 06 / 06','Dokumentacja oceny','Podsumowanie procesu i eksport wyników do pliku lub PDF.',state.finalized?smallStamp('Zakończona','success'):smallStamp('Projekt dokumentu','warning'))}<div class="info-banner"><span class="info-icon">ⓘ</span><div><strong>Wydruk demonstracyjny</strong><p>To nie jest urzędowy formularz. Wybierz „Drukuj / zapisz PDF” i w oknie przeglądarki wybierz drukarkę PDF. Do wdrożenia potrzebne będą oficjalne szablony.</p></div></div><section class="report-preview"><div class="report-preview-head"><div class="report-logo">✦ <strong>Kompas kompetencji</strong></div><small>RAPORT DEMONSTRACYJNY · NIEOFICJALNY</small></div><h2>Podsumowanie oceny</h2><div class="report-meta"><div><small>Pracownik</small><strong>${escapeHtml(state.case.employee)}</strong></div><div><small>Rodzaj oceny</small><strong>${C.tracks[state.case.track].name}</strong></div><div><small>Oceniający</small><strong>${escapeHtml(state.case.manager)}</strong></div><div><small>Okres</small><strong>${fmtDate(state.case.periodStart)} — ${fmtDate(state.case.periodEnd)}</strong></div></div><div class="report-table"><div class="report-table-head"><span>Kompetencja</span><span>Sugestia</span><span>Ocena końcowa</span></div>${t.summaries.map(s=>`<div class="report-table-row"><strong>${s.competency.name}</strong><span>${s.suggestion??'—'} / 4</span><span class="result-strong">${s.final??'—'} / 4 ${s.overruled?'*':''}</span></div>`).join('')}</div><div class="report-bottom"><strong>Ustalenia:</strong> ${escapeHtml(state.meeting.actions || 'Nie zapisano ustaleń.')}</div></section><div class="document-tools"><button class="btn btn-primary" data-action="print">▤ Drukuj / zapisz PDF</button><button class="btn btn-secondary" data-action="export-json">↓ Eksport JSON</button><button class="btn btn-secondary" data-action="export-txt">↓ Eksport TXT</button></div><div class="finalize-box"><div><h3>${state.finalized?'Proces został zakończony':'Zamknij proces oceny'}</h3><p>${state.finalized?'Wynik zapisano w sesji tej karty przeglądarki. Możesz go wyeksportować.':'Zakończenie zapisuje status i datę w lokalnym prototypie.'}</p></div>${state.finalized?smallStamp('✓ Zakończono','success'):button('Zakończ ocenę','finalize','','primary')}</div>`;}
  function renderFirstDocument(){
    const f=state.firstFormal,r=F.evaluate(f);
    return `${pageHeading('ETAP 06 / 06','Arkusz roboczy pierwszej oceny','Podsumowanie pięciu ocen cząstkowych, średniej i warunków z § 10.',state.finalized?smallStamp('Zakończona','success'):smallStamp('Projekt dokumentu','warning'))}
      <div class="info-banner"><span class="info-icon">ⓘ</span><div><strong>Nie jest urzędowym formularzem</strong><p>Ten roboczy wydruk odzwierciedla wybrane pola i reguły z rozporządzenia Dz.U. 2015 poz. 1144, ale nie zastępuje załącznika nr 2 (wzoru arkusza) ani formularza sprawozdania z załącznika nr 3.</p></div></div>
      <section class="report-preview"><h2>Pierwsza ocena — zestawienie robocze</h2><p>${escapeHtml(state.case.employee)} · ${escapeHtml(state.case.position)}</p><div class="report-table"><div class="report-table-head"><span>Element oceny</span><span>Podstawa</span><span>Ocena</span></div>${F.IDS.map(id=>`<div class="report-table-row"><strong>${escapeHtml(E.getCompetency(id).name)}</strong><span>§ 2 ust. 1</span><span class="result-strong">${f.grades?.[id]??'—'} pkt</span></div>`).join('')}</div><div class="report-bottom"><strong>Średnia:</strong> ${r.average===null?'—':r.average.toFixed(2).replace('.',',')} pkt. <strong>Wynik:</strong> ${r.result||'nieustalony'}.<p>${r.negativeReasons.map(escapeHtml).join(' · ')}</p></div></section>
      <div class="document-tools"><button class="btn btn-primary" data-action="print">Drukuj / zapisz PDF (roboczy)</button><button class="btn btn-secondary" data-action="export-json">Eksport JSON</button><button class="btn btn-secondary" data-action="export-txt">Eksport TXT</button></div>
      <p class="field-hint"><a href="https://www.gov.pl/web/sluzbacywilna/pierwsza-ocena" target="_blank" rel="noopener noreferrer">Oficjalne wzory arkusza i sprawozdania (KPRM)</a></p>
      <div class="finalize-box"><div><h3>${state.finalized?'Proces zakończony':'Zamknij proces'}</h3><p>${state.finalized?'Raport roboczy zapisano w bieżącej sesji.':'Wymagane są wszystkie oceny cząstkowe, warunki z § 10 oraz data rozmowy.'}</p></div>${state.finalized?smallStamp('Zakończono','success'):button('Zakończ ocenę','finalize','','primary')}</div>`;
  }
  function renderDocument(){return state.case.track==='first'?renderFirstDocument():renderPeriodicDocument();}
  function renderFooter(){const t=state.step;return `<div class="step-footer"><div>${t>0?button('← Poprzedni etap','prev','','secondary'):(D.current(state)?button('↺ Przywróć sesję','end-demo','','subtle'):button('↺ Wyczyść scenariusz','reset','','subtle'))}</div><div class="footer-middle">Etap ${t+1} z ${steps().length}</div><div>${t<steps().length-1?button('Dalej →','next','','primary'):(state.finalized?smallStamp('Proces zakończony','success'):'')}</div></div>`;}
  function renderHR(){const current=currentStatus(),t=E.totals(state), fake=[['Jan Kowalczyk','Ocena okresowa','Do przygotowania','20.12.2026'],['Maria Zielińska','Pierwsza ocena','W toku','08.12.2026']];return `${pageHeading('PANEL DEMONSTRACYJNY','Monitorowanie procesów','Wgląd w statusy i terminy. Dwie dodatkowe pozycje na liście są wyłącznie przykładowe.',button('← Wróć do oceny','switch-view','data-view="workflow"','secondary'))}<div class="hr-stats"><div class="stat-card"><span>Procesy w widoku</span><strong>3</strong><small>1 aktywny + 2 fikcyjne przykłady</small></div><div class="stat-card"><span>W toku</span><strong>${state.finalized?'1':'2'}</strong><small>Na podstawie scenariuszy demo</small></div><div class="stat-card"><span>Zakończone</span><strong>${state.finalized?'1':'0'}</strong><small>Aktualny proces</small></div></div><div class="panel"><div class="section-title"><h2>Rejestr ocen</h2><p>Tutaj w docelowym systemie pracownik HR śledzi statusy i terminy.</p></div><div class="hr-table-wrap"><table class="hr-table"><thead><tr><th>Pracownik</th><th>Typ</th><th>Status</th><th>Termin</th><th></th></tr></thead><tbody><tr><td><span class="table-avatar">${initials(state.case.employee)}</span><strong>${escapeHtml(state.case.employee)}</strong></td><td>${C.tracks[state.case.track].name}</td><td>${smallStamp(current[0],current[1])}</td><td>${fmtDate(state.case.due)}</td><td><button class="table-link" data-action="switch-view" data-view="workflow">Otwórz →</button></td></tr>${fake.map(x=>`<tr class="muted-row"><td><span class="table-avatar">${initials(x[0])}</span><strong>${x[0]}</strong></td><td>${x[1]}</td><td>${smallStamp(x[2],x[2]==='W toku'?'warning':'neutral')}</td><td>${x[3]}</td><td><span class="demo-only">DEMO</span></td></tr>`).join('')}</tbody></table></div></div><div class="hr-bottom"><div class="tip-card"><strong>Powiadomienia (podgląd)</strong><p>Planowany termin bieżącej oceny: <b>${fmtDate(state.case.due)}</b>.</p><p>W MVP można zobaczyć termin, ale automatyczne wysyłanie przypomnień wymaga backendu i kanału komunikacji.</p></div><div class="tip-card"><strong>Uprawnienia (podgląd)</strong><p>Docelowe role: przełożony, pracownik HR i administrator.</p><p>Ten prototyp nie wdraża uwierzytelniania ani rzeczywistej izolacji danych.</p></div></div>`;}
  function renderAssistant(){const conf=state.assistant;
    const suggestions=['Jakie elementy pierwszej oceny?','Jakie oceny 3, 5 i 7?','Kiedy pierwsza ocena jest pozytywna?'];
    const browserReady=browserAi?.ready()||false;
    const statusLabel=conf.mode==='online'?(onlineConsent?'AI Online · włączony':'AI Online · wymaga zgody'):conf.mode==='offline'?'Tryb źródłowy · bez LLM':conf.mode==='browser'?(browserReady?'AI w przeglądarce · gotowe':'AI w przeglądarce · wymaga uruchomienia'):'Lokalny Ollama · AI';
    const browserAiControls=conf.mode==='browser'?`<div class="browser-ai-settings"><p><strong>Bezpłatna LLM na urządzeniu</strong> · ${escapeHtml(browserAi?.model||'Qwen2.5 0.5B')}. Wymaga WebGPU; pierwsze uruchomienie pobiera duże pliki z internetu (ok. 1 GB pamięci GPU). Pytania są przetwarzane na komputerze, bez klucza API.</p>${browserReady?'<div class="ai-ready">Model załadowany — można zadawać pytania.</div>':`<button type="button" class="btn btn-primary ai-init" data-action="enable-browser-ai" ${browserAiLoading?'disabled':''}>${browserAiLoading?'Ładowanie modelu…':'Uruchom AI w przeglądarce'}</button>`}<div id="ai-progress" class="ai-progress" aria-live="polite">${escapeHtml(browserAiProgress)}</div><small>Wymagana zgodna przeglądarka i GPU. Jeśli model nie działa, użyj trybu Offline. Nie wpisuj danych osobowych.</small></div>`:'';
    const onlineControls=conf.mode==='online'?`<div class="browser-ai-settings ai-online-settings"><strong>AI Online — tylko demonstracja HackNation 2026</strong><p>Pytanie zostanie przesłane do zewnętrznej usługi AI przez zabezpieczony serwer pośredniczący. Wraz z pytaniem przekazywane są fragmenty publicznej bazy wiedzy. <strong>Nie wpisuj danych osobowych, nazwisk ani poufnych informacji pracowników.</strong> Pola ocen, notatki i dokumenty nie są automatycznie przesyłane.</p><p>Wersja produkcyjna może korzystać z modelu lokalnego lub instytucjonalnego. Możesz wybrać Offline, aby nie przesyłać pytań do zewnętrznego dostawcy AI.</p>${window.KOMPAS_ONLINE_AI?.configured()?onlineConsent?'<div class="ai-ready" role="status">AI Online włączony na czas tej wizyty.</div>':'<button type="button" class="btn btn-primary ai-init" data-action="enable-online-ai">Rozumiem i włączam AI Online</button>':'<div class="ai-progress" role="status">Serwer AI nie jest jeszcze skonfigurowany. Wybierz Offline.</div>'}<small>Treści mogą być przetwarzane przez dostawcę API zgodnie z jego polityką. Automatyczny filtr danych osobowych nie daje pełnej gwarancji.</small></div>`:'';
    return `<aside class="assistant" id="knowledge-assistant" aria-label="Asystent wiedzy"><div class="assistant-head"><div class="assistant-top"><div class="assistant-avatar">✳</div><div><h2>Asystent wiedzy</h2><p>Wskazuje źródła, nie ocenia osób</p></div><button type="button" class="assistant-close" data-action="toggle-assistant" aria-label="Zamknij asystenta">×</button></div><div class="assistant-status"><span class="status-dot ${conf.mode!=='offline'?'active':''}"></span> ${escapeHtml(statusLabel)}</div></div><div class="assistant-body"><div class="assistant-intro"><div class="assistant-sparkle">✧</div><h3>W czym mogę pomóc?</h3><p>Zapytaj o proces oceny, obserwowane zachowania lub przygotowanie rozmowy.</p></div><div class="quick-questions">${suggestions.map((s,i)=>`<button data-action="ask-preset" data-q="${escapeHtml(s)}">${s}<span>↗</span></button>`).join('')}</div><div id="assistant-chat" class="chat-history">${conf.chat.map(row=>`<div class="chat-message ${row.role==='user'?'chat-user':'chat-bot'}"><div class="chat-bubble">${escapeHtml(row.text)}</div>${row.sources?.length?`<div class="chat-sources"><span>Źródła:</span> ${row.sources.map(s=>`<a class="source-pill" href="${escapeHtml(s.url||'#')}" target="_blank" rel="noopener noreferrer" title="${escapeHtml(s.title)}">${escapeHtml(s.id)}</a>`).join('')}</div>`:''}${row.mode==='ollama'||row.mode==='browser'||row.mode==='online'?'<small class="chat-mode">Tekst wygenerowany przez LLM; źródła oznaczają kontekst, a nie automatyczną weryfikację odpowiedzi.</small>':''}</div>`).join('')}${conf.busy?'<div class="chat-busy">Model przygotowuje odpowiedź…</div>':''}</div></div><div class="assistant-bottom"><form id="assistant-form"><label class="sr-only" for="assistant-question">Pytanie do asystenta</label><textarea id="assistant-question" rows="2" placeholder="Napisz pytanie o proces…" ${conf.busy?'disabled':''}>${escapeHtml(assistantDraft)}</textarea><button aria-label="Wyślij pytanie" type="submit" class="send-btn" ${conf.busy?'disabled':''}>➤</button></form><div class="assistant-mode"><button data-action="set-mode" data-mode="offline" class="mode-pill ${conf.mode==='offline'?'active':''}">Offline</button><button data-action="set-mode" data-mode="online" class="mode-pill ${conf.mode==='online'?'active':''}">AI Online</button><button data-action="set-mode" data-mode="ollama" class="mode-pill ${conf.mode==='ollama'?'active':''}">Ollama AI</button><button data-action="set-mode" data-mode="browser" class="mode-pill ${conf.mode==='browser'?'active':''}">AI WebGPU</button><button data-action="toggle-settings" class="settings-toggle" title="Ustawienia lokalnego modelu">⚙</button></div>${onlineControls}${browserAiControls}<div class="ollama-settings" id="ollama-settings" hidden><label>Adres lokalnego modelu<input name="assistant.endpoint" data-field="1" value="${escapeHtml(conf.endpoint)}" placeholder="http://localhost:11434"></label><label>Nazwa modelu<input name="assistant.model" data-field="1" value="${escapeHtml(conf.model)}" placeholder="llama3.2:3b"></label><small>Użyj darmowej lokalnej instalacji Ollama. Zewnętrzne API są zablokowane. Nie wpisuj danych osobowych.</small></div><div class="assistant-caveat">Źródła: wybrane przepisy i brief. Odpowiedzi LLM nie są poradą prawną; linki źródłowe wskazują kontekst, nie automatyczną weryfikację twierdzeń. Offline działa bez połączenia z zewnętrznym modelem.</div></div></aside>`;
  }
  function renderPeriodicPrintReport(){const t=E.totals(state), c=state.case, m=state.meeting;
    return `<div class="print-sheet"><div class="print-header"><strong>✦ KOMPAS KOMPETENCJI</strong><span>WERSJA DEMONSTRACYJNA · NIE JEST FORMULARZEM URZĘDOWYM</span></div><h1>Raport z oceny kompetencji</h1><p class="print-intro">Prototyp konkursowy · dane fikcyjne · ${escapeHtml(C.tracks[c.track].name)}</p><table class="print-meta"><tr><th>Pracownik</th><td>${escapeHtml(c.employee)}</td><th>Stanowisko</th><td>${escapeHtml(c.position)}</td></tr><tr><th>Przełożony</th><td>${escapeHtml(c.manager)}</td><th>Departament</th><td>${escapeHtml(c.department)}</td></tr><tr><th>Okres</th><td>${fmtDate(c.periodStart)} – ${fmtDate(c.periodEnd)}</td><th>Termin</th><td>${fmtDate(c.due)}</td></tr></table><h2>Wyniki oceny</h2><table class="print-table"><thead><tr><th>Kompetencja</th><th>Obserwacje</th><th>Sugestia*</th><th>Decyzja kierownika</th></tr></thead><tbody>${t.summaries.map(s=>`<tr><td><strong>${s.competency.name}</strong></td><td>${s.values.join(' / ')}</td><td>${s.suggestion}/4</td><td><strong>${s.final}/4 — ${levelLabel(s.final)}</strong>${s.overruled?`<p>Odstąpienie: ${escapeHtml(state.decisions[s.competency.id]?.reason||'')}</p>`:''}</td></tr>`).join('')}</tbody></table><p class="print-hint">* Sugestia = średnia arytmetyczna wskazań, zaokrąglona do najbliższej liczby całkowitej. Reguła demonstracyjna, nie urzędowa.</p><h2>Przygotowanie rozmowy</h2><div class="print-notes"><strong>Mocne strony:</strong><p>${escapeHtml(m.strengths)||'—'}</p><strong>Obszary rozwoju:</strong><p>${escapeHtml(m.areas)||'—'}</p><strong>Pytania:</strong><p>${escapeHtml(m.questions)||'—'}</p><strong>Dalsze działania:</strong><p>${escapeHtml(m.actions)||'—'}</p></div><h2>Przykłady zaobserwowanych zachowań</h2>${t.summaries.map(s=>`<div class="print-evidence"><strong>${s.competency.name}</strong><ul>${s.competency.indicators.map((label,i)=>{const o=state.observations[E.key(s.competency.id,i)]||{};return `<li>${escapeHtml(label)} — <b>${o.level}/4</b>${o.note?' — '+escapeHtml(o.note):''}</li>`;}).join('')}</ul></div>`).join('')}<div class="print-sign"><span>Data: ___________________</span><span>Podpis osoby oceniającej: ___________________</span></div><div class="print-footer">Kompas Kompetencji — prototyp HackNation 2026. Nie stosować do rzeczywistych ocen kadrowych bez walidacji prawnej, kadrowej i bezpieczeństwa.</div></div>`;
  }
  function renderFirstPrintReport(){
    const c=state.case,f=state.firstFormal,r=F.evaluate(f),m=state.meeting;
    return `<div class="print-sheet"><div class="print-header"><strong>KOMPAS KOMPETENCJI — PIERWSZA OCENA</strong><span>ARKUSZ ROBOCZY · NIE JEST URZĘDOWYM FORMULARZEM</span></div><h1>Pierwsza ocena – podsumowanie pomocnicze</h1><p>Rozporządzenie Prezesa Rady Ministrów z 23.07.2015 r. (Dz.U. 2015 poz. 1144), § 2, 7, 9–10.</p><table class="print-meta"><tr><th>Pracownik</th><td>${escapeHtml(c.employee)}</td><th>Stanowisko</th><td>${escapeHtml(c.position)}</td></tr><tr><th>Oceniający</th><td>${escapeHtml(c.manager)}</td><th>Komórka</th><td>${escapeHtml(c.department)}</td></tr><tr><th>Data rozmowy oceniającej</th><td>${escapeHtml(fmtDate(f.assessmentMeetingDate))}</td><th>Sprawozdanie w terminie</th><td>${f.reportOnTime==='yes'?'Tak':f.reportOnTime==='no'?'Nie':'Nie ustalono'}</td></tr></table><h2>Oceny cząstkowe (skala 3/5/7)</h2><table class="print-table"><thead><tr><th>Element oceny</th><th>Ocena przełożonego</th></tr></thead><tbody>${F.IDS.map(id=>`<tr><td>${escapeHtml(E.getCompetency(id).name)}</td><td>${f.grades?.[id]??'—'} pkt</td></tr>`).join('')}</tbody></table><p><strong>Średnia:</strong> ${r.average===null?'Brak':r.average.toFixed(2).replace('.',',')} pkt. <strong>Wynik wg § 10:</strong> ${r.result||'nieustalony'}.</p><p>Egzamin: ${escapeHtml(f.examStatus||'—')}; wyjątek: ${escapeHtml(f.exemptionKind||'—')}.</p>${r.result==='negatywna'?`<h2>Uzasadnienie oceny negatywnej</h2><p>${escapeHtml(f.negativeReason)}</p>`:''}<h2>Uwagi do rozmowy</h2><p>${escapeHtml(m.strengths||'—')} / ${escapeHtml(m.areas||'—')} / ${escapeHtml(m.actions||'—')}</p><div class="print-sign"><span>Data: ___________________</span><span>Podpis oceniającego: ___________________</span></div><div class="print-footer">WYDRUK ROBOCZY. Nie jest załącznikiem nr 2 do rozporządzenia ani kompletnym arkuszem. Urzędowe formularze: gov.pl/web/sluzbacywilna/pierwsza-ocena. Dane fikcyjne.</div></div>`;
  }
  function renderPrintReport(){return state.case.track==='first'?renderFirstPrintReport():renderPeriodicPrintReport();}
  function render(){
    root.innerHTML=`<div class="app-shell">${renderHeader()}<div class="app-grid ${assistantOpen?'assistant-expanded':'assistant-collapsed'}">${renderSidebar()}${renderMain()}${assistantOpen?'<div class="assistant-backdrop" data-action="toggle-assistant" aria-hidden="true"></div>'+renderAssistant():'<div id="knowledge-assistant" hidden></div>'}</div></div>`;
    document.getElementById('print-report').innerHTML=renderPrintReport();
    const chat=q('#assistant-chat');if(chat)chat.scrollTop=chat.scrollHeight;
  }
  function navigate(target){target=Number(target);const result=SS.navigate(state,target);if(!result.ok){notify(result.message);return;}state.view='workflow';state.notice='';save();render();window.scrollTo(0,0);}
  function updateField(name,value){
    const parts=name.split('.');let obj=state;for(let i=0;i<parts.length-1;i++){const key=parts[i];if(obj[key]===undefined)obj[key]={};obj=obj[key];}
    obj[parts.at(-1)]=value;
    if(parts[0]!=='assistant')invalidate();
    save();
  }
  function applyClick(target){const action=target.dataset.action,id=target.dataset.id;
    switch(action){
      case 'switch-view':state.view=target.dataset.view;state.notice='';save();render();break;
      case 'go-step':navigate(target.dataset.step);break;
      case 'next':navigate(state.step+1);break;
      case 'prev':navigate(Math.max(0,state.step-1));break;
      case 'clear-notice':state.notice='';save();render();break;
      case 'choose-track':{const r=SS.changeTrack(state,id);if(!r.ok){notify(r.message);break;}prototypeDetailsOpen=false;save();render();break;}
      case 'toggle-criterion':{const r=SS.toggleCriterion(state,id);if(!r.ok){notify(r.message);break;}save();render();break;}
      case 'rate':{const r=SS.rate(state,id,Number(target.dataset.index),Number(target.dataset.level));if(!r.ok){notify(r.message);break;}save();render();break;}
      case 'decide':{const r=SS.decide(state,id,Number(target.dataset.level));if(!r.ok){notify(r.message);break;}save();render();break;}
      case 'suggest-questions':state.meeting.questions='Jak oceniasz najważniejsze osiągnięcia w tym okresie?\nKtóre sytuacje były dla Ciebie najbardziej wymagające?\nCo pomogłoby Ci rozwinąć wskazane kompetencje?';invalidate();notify('Dodano przykładowe pytania do rozmowy.');break;
      case 'toggle-assistant':assistantOpen=!assistantOpen;demoMenuOpen=false;render();if(assistantOpen){q('.assistant-close')?.focus();}else{q('.header-assistant-toggle')?.focus();}break;
      case 'toggle-prototype-details':prototypeDetailsOpen=!prototypeDetailsOpen;render();q('.prototype-more-button')?.focus();break;
      case 'toggle-demo-menu':demoMenuOpen=!demoMenuOpen;render();(demoMenuOpen?q('.demo-menu-item'):q('.demo-picker-trigger'))?.focus();break;
      case 'start-demo':{
        const descriptor=D.get(id);if(!descriptor)break;
        if(!window.confirm('Uruchomić scenariusz "'+descriptor.label+'"? Bieżąca sesja zostanie zachowana lokalnie i będzie możliwa do przywrócenia.'))break;
        const loaded=D.begin(id,state);
        if(!loaded.ok){notify(loaded.message);break;}
        if(!S.save(loaded.state)){notify('Nie udało się zapisać scenariusza. Dotychczasowy proces pozostaje bez zmian.');break;}
        state=loaded.state;demoMenuOpen=false;assistantOpen=descriptor.id==='assistant-sources';prototypeDetailsOpen=false;onlineConsent=false;render();break;
      }
      case 'end-demo':{
        if(!window.confirm('Przywrócić sesję sprzed demonstracji? Zmiany wykonane w scenariuszu testowym zostaną zastąpione.'))break;
        const result=D.restore(state);if(!result.ok){notify(result.message);break;}
        state=result.state;demoMenuOpen=false;onlineConsent=false;render();break;
      }
      case 'grade-first':{const r=SS.gradeFirst(state,id,Number(target.dataset.level));if(!r.ok){notify(r.message);break;}save();render();break;}
      case 'jump-results':navigate(5);break;
      case 'reset':if(window.confirm('Wyczyścić wszystkie dane bieżącej sesji?')){state=S.initial();save();render();}break;
      case 'finalize':{const r=SS.finalize(state);if(!r.ok){notify(r.message);break;}notify('Proces zakończony. Raport pozostaje dostępny w bieżącej karcie przeglądarki.');break;}
      case 'print':window.print();break;
      case 'export-json':download(JSON.stringify(exportData(),null,2),'kompas-ocena-demo.json','application/json');break;
      case 'export-txt':download(exportText(),'kompas-ocena-demo.txt','text/plain');break;
      case 'ask-preset':askAssistant(target.dataset.q);break;
      case 'set-mode':state.assistant.mode=target.dataset.mode;save();render();break;
      case 'enable-browser-ai':prepareBrowserAi();break;
      case 'enable-online-ai':if(window.KOMPAS_ONLINE_AI?.configured()){onlineConsent=true;render();}break;
      case 'toggle-settings':{const el=q('#ollama-settings');if(el)el.hidden=!el.hidden;break;}
      default:break;
    }
  }
  function exportPeriodicData(){const t=E.totals(state);return {schema:'kompas-demo-v1',warning:'Demonstracyjny raport, nie jest urzędową oceną.',case:state.case,model:C.schemaVersion,procedure:W.getProcedure(state.case.track).id,procedureSchema:window.KOMPAS_PROCEDURES.schemaVersion,method:'Równe wagi, średnia arytmetyczna, Math.round',competencies:t.summaries.map(s=>({id:s.competency.id,name:s.competency.name,indicators:s.competency.indicators.map((label,i)=>({text:label,...(state.observations[E.key(s.competency.id,i)]||{})})),average:s.average,explanation:s.explanation,suggested:s.suggestion,managerDecision:s.final,reason:state.decisions[s.competency.id]?.reason||''})),meeting:state.meeting,status:state.finalized?'completed':'draft',completedAt:state.finalizedAt,technicalHistory:(state.history||[])};}
  function exportPeriodicText(){const d=exportPeriodicData();return `KOMPAS KOMPETENCJI — RAPORT DEMONSTRACYJNY (NIEURZĘDOWY)\n\nPracownik: ${d.case.employee}\nRodzaj: ${C.tracks[d.case.track].name}\nPrzełożony: ${d.case.manager}\nOkres: ${d.case.periodStart} – ${d.case.periodEnd}\n\n${d.competencies.map(c=>`${c.name}: sugestia ${c.suggested}/4; decyzja ${c.managerDecision}/4${c.reason?' (uzasadnienie: '+c.reason+')':''}\n${c.indicators.map(x=>`  - ${x.text}: ${x.level}/4${x.note?' — '+x.note:''}`).join('\n')}`).join('\n\n')}\n\nMocne strony: ${d.meeting.strengths}\nObszary do rozwoju: ${d.meeting.areas}\nPytania: ${d.meeting.questions}\nDalsze działania: ${d.meeting.actions}\n\nUWAGA: skala i model są przykładowe; brak walidacji względem prawnych formularzy.`;}
  function exportData(){
    if(state.case.track!=='first')return exportPeriodicData();
    const r=F.evaluate(state.firstFormal);
    return {schema:'kompas-first-0.4',warning:'ROBOCZY RAPORT — nie jest urzędowym formularzem pierwszej oceny',regulation:'Dz.U. 2015 poz. 1144 § 2, 7, 9–10',case:state.case,firstAssessment:{...state.firstFormal,result:r.result,average:r.average,lowCount:r.lowCount,negativeReasons:r.negativeReasons},elements:F.IDS.map(id=>({id,name:E.getCompetency(id).name,managerGrade:state.firstFormal.grades?.[id]??null,evidence:E.getCompetency(id).indicators.map((label,i)=>({label,...state.observations[E.key(id,i)]}))})),meeting:state.meeting,status:state.finalized?'completed':'draft',completedAt:state.finalizedAt,technicalHistory:state.history||[]};
  }
  function exportText(){
    if(state.case.track!=='first')return exportPeriodicText();
    const d=exportData(),r=d.firstAssessment;
    return `KOMPAS KOMPETENCJI — PIERWSZA OCENA (ARKUSZ ROBOCZY, NIEURZĘDOWY)\nPodstawa: Dz.U. 2015 poz. 1144, § 2, 7, 9–10.\n\nPracownik: ${d.case.employee}\nOceniający: ${d.case.manager}\n\n${d.elements.map(x=>x.name+': '+(x.managerGrade??'—')+' pkt').join('\n')}\n\nŚrednia: ${r.average??'nieustalona'}\nWynik: ${r.result||'nieustalony'}\nEgzamin: ${r.examStatus}\nSprawozdanie w terminie: ${r.reportOnTime}\nUzasadnienie: ${r.negativeReason}\n\nUWAGA: Nie zastępuje wzoru arkusza urzędowego ani załączników.`;
  }
  function download(data,fileName,mime){const url=URL.createObjectURL(new Blob([data],{type:mime+';charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=fileName;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function prepareBrowserAi(){
    if(browserAiLoading||browserAi?.ready())return;
    browserAiLoading=true;browserAiProgress='Sprawdzanie obsługi WebGPU…';render();
    try{
      await browserAi.prepare(progress=>{browserAiProgress=progress;const el=q('#ai-progress');if(el)el.textContent=progress;});
      browserAiProgress='Model gotowy. Możesz zadawać pytania.';
    }catch(error){
      browserAiProgress='Nie można uruchomić AI: '+String(error.message||error).slice(0,240);
    }finally{browserAiLoading=false;render();}
  }
  async function askAssistant(text){
    if(state.assistant.busy)return;
    const queryText=(text||'').trim();if(!queryText)return;
    if(state.assistant.mode==='online') {
      if(!onlineConsent){notify('Przed użyciem AI Online świadomie włącz ten tryb.');return;}
      if(window.KOMPAS_ONLINE_AI?.looksPrivate(queryText)){notify('Nie wysyłaj danych osobowych ani informacji o konkretnych pracownikach do AI Online.');return;}
    }
    assistantDraft='';state.assistant.chat.push({role:'user',text:queryText});state.assistant.busy=true;save();render();
    try{
      const response=await A.ask(queryText,{mode:state.assistant.mode,endpoint:state.assistant.endpoint,model:state.assistant.model});
      state.assistant.chat.push({role:'assistant',...response,sources:(response.sources||[]).map(s=>({id:s.id,title:s.title,url:s.url||''}))});
    }catch(e){
      const fallback=A.offline(queryText);
      state.assistant.chat.push({role:'assistant',text:'Usługa AI jest niedostępna lub zapytanie odrzucono ('+String(e.message).slice(0,160)+'). Tryb Offline: '+fallback.text,sources:fallback.sources.map(s=>({id:s.id,title:s.title,url:s.url||''})),mode:'offline'});
    }finally{state.assistant.busy=false;save();render();}
  }
  root.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target&&root.contains(target))applyClick(target);else if(demoMenuOpen && !e.target.closest('.demo-picker')){demoMenuOpen=false;render();}});
  document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if(demoMenuOpen){demoMenuOpen=false;render();q('.demo-picker-trigger')?.focus();}else if(assistantOpen){assistantOpen=false;render();q('.header-assistant-toggle')?.focus();}});
  root.addEventListener('input',e=>{const t=e.target;if(t.id==='assistant-question')assistantDraft=t.value;if(t.matches('[data-field]'))updateField(t.name,t.value);});
  root.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-field]')){updateField(t.name,t.value);}});
  root.addEventListener('submit',e=>{if(e.target?.id==='assistant-form'){e.preventDefault();const field=q('#assistant-question');askAssistant(field?.value||'');}});
  root.addEventListener('keydown',e=>{if(e.target?.id==='assistant-question'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();askAssistant(e.target.value);}});
  window.KOMPAS_DEBUG={getDemo:()=>D.current(state),getState:()=>JSON.parse(JSON.stringify(state)),totals:()=>E.totals(state),procedure:()=>W.getProcedure(state.case.track),canNavigate:target=>W.canNavigate(state,target),fillDemo:()=>{S.fillDemo(state);save();render();}};
  render();
})();
